import {qualitativeContext} from './career-insights.js?v=0.31.0';
import {commonCostEvidence} from './common-cost-data.js?v=0.31.0';
import {occupationEssentials,essentialMetadata} from './occupation-essentials.js?v=0.31.0';
import {careerConnection,taskAreasFor,taskPrompts,interestNames} from './matching.js?v=0.31.0';
import {escapeHTML as h} from './model.js?v=0.31.0';
import {occupations} from './occupation-data.js?v=0.31.0';
const more=(body,label)=>`<details class="more-info"><summary>${label}</summary><div>${body}</div></details>`;
const tags=items=>`<ul class="profile-tags">${items.slice(0,3).map(x=>`<li>${h(typeof x==='string'?x:x.name)}</li>`).join('')}</ul>`;
const plain={'Troubleshooting':'Find and fix problems','Repairing':'Fix equipment','Cautiousness':'Work carefully','Active Learning':'Learn new skills','Systems Analysis':'Understand how parts work together','Operations Analysis':'Work out what a project needs','Quality Control Analysis':'Check work for mistakes','Analytical Thinking':'Think through problems','Active Listening':'Listen carefully','Critical Thinking':'Think through choices','Reading Comprehension':'Understand written information','Speaking':'Explain clearly','Social Perceptiveness':'Notice how others feel','Monitoring':'Notice what needs to change','Coordination':'Work smoothly with others','Service Orientation':'Look for ways to help','Judgment and Decision Making':'Make careful decisions','Complex Problem Solving':'Work through difficult problems','Time Management':'Manage time','Attention to Detail':'Care with details','Stress Tolerance':'Stay steady under pressure','Dependability':'Follow through','Adaptability':'Adjust when things change','Integrity':'Act honestly','Achievement Orientation':'Keep improving','Intellectual Curiosity':'Stay curious','Cooperation':'Work well with others','Concern for Others':'Care about people','Self-Control':'Manage strong emotions','Initiative':'Get started','Persistence':'Keep going','Perseverance':'Keep going','Oral Comprehension':'Understand spoken information','Oral Expression':'Explain ideas aloud','Problem Sensitivity':'Notice a problem early','Deductive Reasoning':'Apply rules to a problem','Inductive Reasoning':'Connect clues','Written Comprehension':'Understand written information','Near Vision':'See close details','Manual Dexterity':'Use hands precisely','Finger Dexterity':'Make small, precise movements'};
const friendly=items=>items.map(x=>plain[x.name||x]||x.name||x);
export function matchNote(state,o){const m=careerConnection(state,o);return m.taskCount?`<div class="profile-match match-positive"><strong>${h(m.label)}</strong><p>${h(m.reasons.slice(0,2).join(' '))}</p></div>`:m.themeCount?`<div class="profile-match match-positive"><strong>Worth exploring</strong><p>Your broad interests include ${h(m.themes.map(t=>interestNames[t].toLowerCase()).join(' and '))}.</p></div>`:'';}
export function occupationProfilePanels(o,state){const e=occupationEssentials[o.soc],skills=e?.skills?.length?friendly(e.skills):o.skills,habits=e?.workStyles?.length?friendly(e.workStyles):o.workStyles,abilities=e?.abilities?.length?friendly(e.abilities):o.abilities,knowledge=e?.knowledge?.length?e.knowledge:o.knowledge;
 const context=(o.context?.items||[]).filter(x=>!x.suppressedCategoryCount&&x.responses?.length&&['Work Schedules','Time Pressure','Contact With Others','Work With or Contribute to a Work Group or Team','Spend Time Standing'].includes(x.name)).slice(0,3);
 const related=(o.relatedIds||[]).map(id=>occupations.find(x=>x.id===id||x.soc===id)).filter(Boolean).filter(x=>x.id!==o.id).slice(0,3);
 return `${qualitativeContext[o.id]?'<section class="profile-panel"><span class="overline">WORKING LIFE</span><h2>Picture the setting.</h2><ul>'+qualitativeContext[o.id].facts.map(t=>'<li>'+h(t)+'</li>').join('')+'</ul>'+more('<a href="'+qualitativeContext[o.id].sourceURL+'" target="_blank" rel="noopener">Official work setting source ↗</a>','About this work setting')+'</section>':''}${matchNote(state,o)}<div class="profile-grid"><section class="profile-panel skills"><span class="overline">SKILLS TO BUILD</span><h2>What helps with the work.</h2>${tags(skills)}${more(tags(abilities)+'<p>These describe abilities used in the occupation. They do not measure your ability today.</p>','Abilities you can develop')}</section><section class="profile-panel habits"><span class="overline">HELPFUL QUALITIES</span><h2>Habits that matter.</h2>${tags(habits)}<p>These can grow with practice.</p></section></div><section class="profile-panel task-themes"><span class="overline">WHAT MIGHT DRAW YOU IN</span><h2>Which parts sound like you?</h2><div class="profile-task-interests">${taskAreasFor(o).map(t=>`<span>${h(taskPrompts[t])}</span>`).join('')||'<p>Explore the daily tasks above and notice what holds your interest.</p>'}</div>${more('<p>Fieldguide connects your chosen activities with O*NET occupation descriptors. These are exploration prompts, not a validated fit score or a reason to close a door.</p>','How we connect your interests')}</section>${context.length?`<section class="profile-panel"><span class="overline">WORKING LIFE</span><h2>The setting matters too.</h2><div class="profile-context">${context.map(x=>{const modal=[...x.responses].sort((a,b)=>b.percent-a.percent)[0];return `<article><strong>${h({'Work With or Contribute to a Work Group or Team':'Teamwork','Contact With Others':'People','Work Schedules':'Schedule','Time Pressure':'Time pressure','Spend Time Standing':'Standing'}[x.name])}</strong><p>${h(modal.label)}</p></article>`;}).join('')}</div>${more('<p>Most common response in the O*NET national occupation survey, not a promise about an Austin employer.</p>'+context.map(x=>`<p>${h(x.name)}: ${h([...x.responses].sort((a,b)=>b.percent-a.percent)[0].percent)}% · source ${h(x.referenceDate)}.</p>`).join(''),'About these work settings')}</section>`:''}${more(`<h3>Knowledge to build</h3>${tags(knowledge)}<h3>Duties from O*NET</h3><ul>${o.tasks.map(t=>`<li>${h(t.text)}</li>`).join('')}</ul><p>Includes O*NET®31.0 Database content, U.S. Department of Labor. Selected descriptors and Fieldguide plain-language summaries. Interest and work-style descriptors include expert and AI-assisted sources; they are not student measurements.</p><a href="${h(o.url)}" target="_blank" rel="noopener noreferrer">Full official occupation profile ↗</a> · <a href="${essentialMetadata.licenseURL}" target="_blank" rel="noopener noreferrer">CC BY 4.0 ↗</a>`,'Duties, knowledge & sources')}${related.length?`<section class="profile-panel"><span class="overline">RELATED POSSIBILITIES</span><h2>Keep another door open.</h2><div class="related-profile-links">${related.map(x=>`<a href="#/career/${x.id}">${h(x.title)} →</a>`).join('')}</div></section>`:''}`;
}

export function trainingCostPreview(id){if(id==='electrician')return `<section class="cost-quick-reference"><span class="overline">PREPARATION COST · ONE PROGRAM EXAMPLE</span><h3>Austin ETA paid apprenticeship</h3><strong>$35 application fee</strong><p>Four years. Paid work plus classes. Tuition and tools cost extra.</p>${more('<p>The current program page says tuition is announced before classes. Its $825 tuition notice covers September 2025–August 2026 and is a past reference, not the next class price. Admission is competitive; the fee does not secure a place. Texas registration or licensing fees, tools, books, and travel may add costs.</p><p>Checked October 16, 2026. <a href="https://austineta.org/apprentice-program-2/" target="_blank" rel="noopener noreferrer">Official Austin ETA program and cost information ↗</a></p>','Cost details & what’s extra')}</section>`;const e=commonCostEvidence[id];return e?`<section class="cost-quick-reference"><span class="overline">PREPARATION COST</span><h3>${h(e.headline)}</h3><strong>${h(e.amountLabel)}</strong><p>${h(e.scope)}</p>${e.status==='published-undated'?'<p>Published example · price year not stated.</p>':''}${more('<p>'+h(e.detail)+'</p><p>Checked '+h(e.checkedAt)+'. '+h(e.status==='published-undated'?'Published example · price year not stated':e.status==='derived'?'Calculated planning estimate':'Published reference')+'.</p><p>'+e.sourceURLs.map(u=>'<a href="'+h(u)+'" target="_blank" rel="noopener noreferrer">Official cost source ↗</a>').join(' · ')+'</p>','Cost details & what’s extra')}</section>`:'';}
